const D = { energy: .6, scale: 1, speed: 1, density: .55, sheen: .6, hue: 44, x: .5, y: .5, style: 'brocade', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// -----------------------------------------------------------------------------
// DAMASK -- an ogee (pointed-arch) net of pomegranate / palmette motifs tiled in
// a mirrored half-drop across the frame, woven as gilt figure on a deep ground.
// The pattern itself is fixed; what lives is the satin: a broad band of gilding
// sheen sweeps diagonally across, with a trailing shadow, so the figure catches
// the light and darkens again exactly the way woven damask flips figure and ground
// as you tilt it. Gold brocade, silver on charcoal, blackwork on linen, or toile.
// -----------------------------------------------------------------------------

const u = Math.min(width, height);
const sd = (P.seed | 0);
const fr = i => { let h = (Math.imul((i ^ sd) | 0, 374761393) + 0x9e3779b9) | 0; h = Math.imul(h ^ (h >>> 15), 668265263); h ^= h >>> 13; return ((h >>> 0) % 100000) / 100000; };

const st = P.style;
let grd, figLo, figHi, figEdge;
if (st === 'silver') { grd = [220, 10, 12]; figLo = [220, 8, 34]; figHi = [210, 4, 82]; figEdge = [200, 3, 100]; }
else if (st === 'blackwork') { grd = [40, 12, 60]; figLo = [30, 20, 14]; figHi = [32, 14, 30]; figEdge = [34, 8, 46]; }
else if (st === 'toile') { grd = [42, 10, 64]; figLo = [224, 62, 26]; figHi = [220, 58, 42]; figEdge = [216, 40, 58]; }
else { grd = [(P.hue + 165) % 360, 60, 15]; figLo = [(P.hue - 8 + 360) % 360, 70, 30]; figHi = [(P.hue + 6) % 360, 52, 84]; figEdge = [(P.hue + 12) % 360, 32, 100]; } // brocade

// ---- adaptive high-res field buffer, rebuilt on size/seed/density/style -----
const BW = Math.max(360, Math.min(720, Math.round(width / 2.4)));
const BH = Math.max(120, Math.round(BW * height / width));
const cols = 3 + Math.round(P.density * 2);              // 3..5 motif columns
const key = BW + 'x' + BH + '|' + P.seed + '|' + cols + '|' + st + '|' + (P.scale.toFixed(2));
if (S.key !== key || !S.field) {
  S.key = key;
  const g = createGraphics(BW, BH); g.colorMode(HSB, 360, 100, 100, 100); g.noStroke();
  g.background(grd[0], grd[1], grd[2]);
  // ground grain so it is not flat
  for (let i = 0; i < 2600; i++) { const gx = fr(i * 2 + 1) * BW, gy = fr(i * 2 + 2) * BH; g.fill(grd[0], grd[1] + 6, grd[2] + (fr(i) - 0.4) * 14, 22); g.rect(gx, gy, 1.4, 1.4); }
  const cw = BW / cols, ch = cw * 1.32 / P.scale;
  const rows = Math.ceil(BH / ch) + 2;

  function motif(cx, cy, w, h, mir) {
    g.push(); g.translate(cx, cy); if (mir) g.scale(-1, 1);
    // ogee cell frame (pointed vesica) -- gilt stroke via layered fills
    function ogee(sw, col, a) {
      g.noFill(); g.stroke(col[0], col[1], col[2], a); g.strokeWeight(sw);
      g.beginShape();
      g.vertex(0, -h * 0.5);
      g.bezierVertex(w * 0.42, -h * 0.36, w * 0.5, -h * 0.06, w * 0.36, h * 0.16);
      g.bezierVertex(w * 0.2, h * 0.36, w * 0.08, h * 0.42, 0, h * 0.5);
      g.bezierVertex(-w * 0.08, h * 0.42, -w * 0.2, h * 0.36, -w * 0.36, h * 0.16);
      g.bezierVertex(-w * 0.5, -h * 0.06, -w * 0.42, -h * 0.36, 0, -h * 0.5);
      g.endShape();
    }
    ogee(w * 0.06, figLo, 90); ogee(w * 0.03, figHi, 100); ogee(w * 0.012, figEdge, 70);
    g.noStroke();
    // central pomegranate body
    g.fill(figLo[0], figLo[1], figLo[2], 100); g.ellipse(0, h * 0.02, w * 0.30, h * 0.34);
    g.fill(figHi[0], figHi[1], figHi[2] * 0.9, 100); g.ellipse(-w * 0.03, h * -0.01, w * 0.20, h * 0.24);
    g.fill(figEdge[0], figEdge[1], figEdge[2], 80); g.ellipse(-w * 0.05, h * -0.03, w * 0.09, h * 0.11);
    // crown of points (palmette) at top of body
    for (let p = -3; p <= 3; p++) { const px = p * w * 0.035; g.fill(figHi[0], figHi[1], figHi[2], 100); g.triangle(px, -h * 0.13, px - w * 0.02, -h * 0.24 - Math.abs(p) * h * 0.006, px + w * 0.02, -h * 0.13); }
    // side leaves curling out
    for (const sgn of [-1, 1]) {
      g.fill(figLo[0], figLo[1], figLo[2] + 6, 100);
      g.beginShape(); g.vertex(sgn * w * 0.1, h * 0.06);
      g.bezierVertex(sgn * w * 0.34, h * 0.0, sgn * w * 0.44, -h * 0.14, sgn * w * 0.34, -h * 0.24);
      g.bezierVertex(sgn * w * 0.3, -h * 0.12, sgn * w * 0.2, -h * 0.02, sgn * w * 0.1, h * 0.06);
      g.endShape(g.CLOSE);
      g.fill(figHi[0], figHi[1], figHi[2], 70);
      g.beginShape(); g.vertex(sgn * w * 0.13, h * 0.04); g.bezierVertex(sgn * w * 0.3, -h * 0.02, sgn * w * 0.36, -h * 0.13, sgn * w * 0.3, -h * 0.2); g.bezierVertex(sgn * w * 0.26, -h * 0.1, sgn * w * 0.2, -h * 0.02, sgn * w * 0.13, h * 0.04); g.endShape(g.CLOSE);
    }
    // tendrils linking to next cell (top/bottom filler)
    g.stroke(figHi[0], figHi[1], figHi[2], 70); g.strokeWeight(w * 0.02); g.noFill();
    g.line(0, -h * 0.5, 0, -h * 0.62); g.line(0, h * 0.5, 0, h * 0.62);
    g.noStroke();
    g.pop();
  }

  for (let r = -1; r < rows; r++) {
    const drop = (r % 2) ? cw * 0.5 : 0;                  // half-drop
    for (let c = -1; c <= cols; c++) {
      const mx = c * cw + drop, my = r * ch + ch * 0.5;
      motif(mx, my, cw, ch, (c + r) % 2 === 0);
    }
  }
  g.noStroke();
  S.field = g;
}

// ---- animation: sheen band + shadow band sweep across -----------------------
const sp = 0.3 + P.speed * 0.9;
const sheenAmt = (0.4 + P.sheen * 0.9) * (0.6 + P.energy * 0.8) + A.rms * 0.2;
const ang = 0.9 + 0.35 * Math.sin(K.t * 0.06 * sp);       // sweep direction drifts
const sweep = (K.t * 0.11 * sp) % 1;                       // 0..1 travels (wraps smoothly since band is soft & offscreen at wrap)
const diag = Math.hypot(width, height);

push();
image(S.field, 0, 0, width, height);

// bright gilding sheen band (ADD), broad + partial amplitude (no strobe)
const dc = drawingContext;
const cX = Math.cos(ang), cY = Math.sin(ang);
// build a soft triangular band via three stops, centred at `center` (0..1) along the sweep axis
function sweepBand(center, halfW, mode, peakAlpha) {
  const xa = width * 0.5 + cX * (center - 0.5) * diag, ya = height * 0.5 + cY * (center - 0.5) * diag;
  const grad = dc.createLinearGradient(xa - cX * halfW * diag, ya - cY * halfW * diag, xa + cX * halfW * diag, ya + cY * halfW * diag);
  if (mode === 'add') {
    grad.addColorStop(0, 'rgba(255,240,200,0)');
    grad.addColorStop(0.5, 'rgba(255,238,205,' + peakAlpha + ')');
    grad.addColorStop(1, 'rgba(255,240,200,0)');
    blendMode(ADD);
  } else {
    grad.addColorStop(0, 'rgba(255,255,255,0)');
    grad.addColorStop(0.5, 'rgba(6,4,10,' + peakAlpha + ')');
    grad.addColorStop(1, 'rgba(255,255,255,0)');
    blendMode(MULTIPLY);
  }
  dc.save(); dc.fillStyle = grad; dc.fillRect(0, 0, width, height); dc.restore();
}
sweepBand(sweep, 0.26, 'add', Math.min(0.6, 0.32 * sheenAmt));
sweepBand((sweep + 0.5) % 1, 0.22, 'mult', Math.min(0.5, 0.28 * (0.5 + P.sheen)));
blendMode(BLEND);
pop();

blendMode(BLEND);
if (P.alpha < 100) { push(); noStroke(); rectMode(CORNER); fill(grd[0], grd[1], grd[2], 100 - Math.max(0, Math.min(100, P.alpha))); rect(0, 0, width, height); pop(); }
drawingContext.shadowBlur = 0;
